#!/usr/bin/env python3
# admin-device-v3: お店の端末の「登録を外す」を⚙の中にしまう（うっかり押さないため）
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"docs/admin/admin.js": {"old": "eeef0fe5c6271d8f0d7a500c77bed20a", "new": "9e2a880b230139b80bb54140a82b0be7", "data": ""}, "docs/admin/admin.css": {"old": "cfcfad01d30f83c7bee1c6f6c312df47", "new": "3af134a909b70942d9c4da1802b2b188", "data": ""}, "docs/admin/index.html": {"old": "9148a2eb19f96cb7328908a0a84c901e", "new": "76a2d63aa5c0a4630e76a26033b5e5a4", "data": ""}, "tests/e2e_device_test.py": {"old": "ee636e44b57516090894402632805dd9", "new": "74ad8ecd890082deb0145df56b48f514", "data": ""}}')
os.chdir(os.path.dirname(os.path.abspath(__file__)))
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    if os.path.exists(p): shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新" if FILES[p]["old"] else "追加", p)
print("admin-device-v3 OK")
